import 'package:basics/basics.dart';

void main() async {
  const numbers = <int>[2, 4, 8];
  if (numbers.all((n) => n.isEven)) {
    print('All numbers are even.');
  }
  print('sum of numbers is: ${numbers.sum()}');
  for (var _ in 5.range) {
    await Future.delayed(500.milliseconds);
  }
}
